head.b:template-skin:

body#layout .site-header, body#layout .site-footer, body#layout .container { position: static; width: auto; }
body#layout .home-only { display: block; }
body#layout .section { margin: 10px 0; }

body.script:
  //
(function () {
  var header = document.getElementById('site-header');
  var isHome = document.body.classList.contains('is-home');
  if (header && isHome) {
    var onScroll = function () { header.classList.toggle('scrolled', window.scrollY > 60); };
    window.addEventListener('scroll', onScroll, { passive: true });
    onScroll();
  }

  // ----- Connected topics (current labels) -----
  var PILLARS = [
    { name: 'Holidays & Seasons', url: '/search/label/Holidays%20%26%20Seasons', labels: ['Holidays & Seasons'] },
    { name: 'Money & Daily Life', url: '/search/label/Money%20%26%20Daily%20Life', labels: ['Money & Daily Life'] }
  ];

  function feedFor(label) {
    if (window.__feedMock) return Promise.resolve(window.__feedMock[label || '*'] || []);
    var path = label ? '/feeds/posts/summary/-/' + encodeURIComponent(label) : '/feeds/posts/summary';
    return fetch(path + '?alt=json&max-results=25')
      .then(function (r) { return r.ok ? r.json() : { feed: {} }; })
      .then(function (d) {
        return (d.feed.entry || []).map(function (e) {
          var link = (e.link || []).filter(function (l) { return l.rel === 'alternate'; })[0];
          var thumb = e.media$thumbnail ? e.media$thumbnail.url.replace(/\/s\d+(-c)?\//, '/w400-h267-c/').replace(/=s\d+(-c)?$/, '=w400-h267-c') : '';
          return { title: e.title.$t, url: link ? link.href : '#', date: e.published.$t, thumb: thumb };
        });
      })
      .catch(function () { return []; });
  }
  function postsFor(labels) {
    return Promise.all(labels.map(feedFor)).then(function (lists) {
      var seen = {}, all = [];
      lists.forEach(function (list) { list.forEach(function (p) { if (!seen[p.url]) { seen[p.url] = 1; all.push(p); } }); });
      return all.sort(function (a, b) { return a.date < b.date ? 1 : -1; });
    });
  }
  function el(tag, cls, text) { var n = document.createElement(tag); if (cls) n.className = cls; if (text) n.textContent = text; return n; }
  function fmtDate(iso) {
    try { return new Date(iso).toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' }).toUpperCase(); }
    catch (e) { return ''; }
  }

  // Home: topic cards — newest posts of each topic.
  document.querySelectorAll('.mc-tcard[data-labels]').forEach(function (box) {
    var list = box.querySelector('.mc-tcard-posts');
    if (!list) return;
    postsFor(box.getAttribute('data-labels').split('|')).then(function (posts) {
      posts.slice(0, 3).forEach(function (p) {
        var li = el('li'), a = el('a', '', p.title);
        a.href = p.url;
        li.appendChild(a);
        li.appendChild(el('span', '', fmtDate(p.date)));
        list.appendChild(li);
      });
    });
  });

  // Home: featured guide — the newest post on the blog.
  var fT = document.getElementById('mc-feat-title');
  if (fT) {
    postsFor([null]).then(function (posts) {
      if (!posts.length) return;
      var p = posts[0];
      fT.textContent = p.title;
      var lk = document.getElementById('mc-feat-link');
      if (lk) lk.href = p.url;
      var im = document.getElementById('mc-feat-img');
      if (im && p.thumb) im.src = p.thumb.replace('/w400-h267-c/', '/w1000-h667-c/').replace('=w400-h267-c', '=w1000-h667-c');
    });
  }

  // Home: season spotlight — newest Holidays & Seasons posts.
  var sL = document.getElementById('mc-season-list');
  if (sL) {
    postsFor(['Holidays & Seasons']).then(function (posts) {
      sL.innerHTML = '';
      posts.slice(0, 3).forEach(function (p, i) {
        var li = el('li'), a = el('a', '', p.title);
        a.href = p.url;
        li.appendChild(a);
        li.appendChild(el('span', '', i === 0 ? 'NEWEST' : 'GUIDE'));
        sL.appendChild(li);
      });
    });
  }

  // Post page: "Keep reading" — other posts in the same topic.
  var next = document.getElementById('journey-next');
  if (next) {
    var tags = Array.prototype.map.call(document.querySelectorAll('.post-tags a'), function (a) { return a.textContent.replace(/^#/, '').trim(); });
    var pillar = PILLARS.filter(function (pl) { return pl.labels.some(function (l) { return tags.indexOf(l) !== -1; }); })[0];
    if (!pillar) pillar = { name: 'the blog', url: '/search', labels: [null] };
    if (pillar) {
      var here = location.pathname;
      postsFor(pillar.labels).then(function (posts) {
        var others = posts.filter(function (p) { return p.url.indexOf(here) === -1; }).slice(0, 3);
        if (!others.length) return;
        next.querySelector('.journey-pillar').textContent = pillar.name;
        next.querySelector('.journey-all').href = pillar.url;
        var wrap = next.querySelector('.journey-list');
        others.forEach(function (p, i) {
          var a = el('a', 'journey-item'); a.href = p.url;
          var th = el('span', 'journey-thumb');
          if (p.thumb) { var img = el('img'); img.src = p.thumb; img.alt = ''; img.loading = 'lazy'; th.appendChild(img); }
          var tx = el('span');
          tx.appendChild(el('span', 'journey-kicker', i === 0 ? 'Next up' : (pillar.labels[0] ? pillar.name : 'Latest')));
          tx.appendChild(el('span', 'journey-name', p.title));
          a.appendChild(th); a.appendChild(tx); wrap.appendChild(a);
        });
        next.hidden = false;
      });
    }
  }

  var toggle = document.querySelector('.nav-toggle');
  var nav = document.getElementById('site-nav');
  if (toggle && nav) {
    toggle.addEventListener('click', function () {
      var open = nav.classList.toggle('open');
      toggle.setAttribute('aria-expanded', open);
    });
    nav.addEventListener('click', function (e) {
      if (e.target.tagName !== 'A') return;
      nav.classList.remove('open');
      toggle.setAttribute('aria-expanded', false);
    });
  }

  var items = document.querySelectorAll('.reveal');
  if ('IntersectionObserver' in window) {
    var io = new IntersectionObserver(function (entries) {
      entries.forEach(function (en) {
        if (en.isIntersecting) { en.target.classList.add('in'); io.unobserve(en.target); }
      });
    }, { threshold: 0.1 });
    items.forEach(function (el, n) { el.style.transitionDelay = (n % 3) * 90 + 'ms'; io.observe(el); });
  } else {
    items.forEach(function (el) { el.classList.add('in'); });
  }

  var year = document.getElementById('year');

  function mcThanksgiving(y){var d=new Date(y,10,1);d.setDate(1+((4-d.getDay()+7)%7)+21);return d;}
  function mcCountdown(){var box=document.getElementById('mc-hols');if(!box)return;var now=new Date();now.setHours(0,0,0,0);var y=now.getFullYear();var L='/search/label/Holidays%20%26%20Seasons';var list=[{e:'&#127875;',n:'Halloween',f:function(yy){return new Date(yy,9,31);}},{e:'&#129411;',n:'Thanksgiving',f:mcThanksgiving},{e:'&#127876;',n:'Christmas',f:function(yy){return new Date(yy,11,25);}},{e:'&#127886;',n:"New Year's Day",f:function(yy){return new Date(yy+1,0,1);}}];var rows=list.map(function(h){var t=h.f(y);if(t<now)t=h.f(y+1);var d=Math.round((t-now)/864e5);var ds=d===0?'Today!':(d===1?'1 day':d+' days');var dt=t.toLocaleDateString('en-US',{month:'short',day:'numeric'});return{d:d,html:"<a class='mc-hol' href='"+L+"'><span class='mc-hol-em'>"+h.e+"</span><span class='mc-hol-tx'><span class='mc-hol-name'>"+h.n+"</span><br/><span class='mc-hol-date'>"+dt+"</span></span><span class='mc-hol-days'>"+ds+"</span></a>"};}).sort(function(a,b){return a.d-b.d;});box.innerHTML=rows.map(function(r){return r.html;}).join('');}
  function mcRailFresh(){var box=document.getElementById('mc-rail-fresh');if(!box)return;fetch('/feeds/posts/default?alt=json&max-results=3').then(function(r){return r.json()}).then(function(j){var es=(j.feed&&j.feed.entry)||[];if(!es.length){box.innerHTML='<li><span>No posts yet.</span></li>';return;}box.innerHTML=es.map(function(e){var l='';(e.link||[]).forEach(function(a){if(a.rel==='alternate')l=a.href});return '<li><a href="'+l+'">'+e.title.$t+'</a><span>'+e.published.$t.slice(0,10)+'</span></li>'}).join('')}).catch(function(){box.innerHTML='<li><span>Could not load.</span></li>'});}
  mcCountdown();mcRailFresh();
if (year) year.textContent = new Date().getFullYear();
})();

  //
